mapper.select:
    	select  FEE_ID id,
    			FEE_NAME text
    	from MST_FEEINFO



					  and APPLY_TYPE in (#{relationChannel}, #{relationOther})
					  and CHARGE_TYPE = #{CHARGE_TYPE_01}


					  APPLY_TYPE = #{relationProd}




					  and FEE_TYPE = #{feeTypeFloat}


					  and FEE_TYPE in (#{fee10}, #{fee11}, #{fee99})


					  and FEE_TYPE in (#{feeTypeTrust}, #{feeTypeFix}, #{feeTypeSale}, #{feeTypeOthSale}, #{feeTypeThService},#{feeTypeInvest})



				  and (FEE_ID like concat(concat('%', #{search}), '%') or FEE_NAME like concat(concat('%', #{search}), '%'))


				  and (FEE_ID IN (#{initValue}) or FEE_NAME IN (#{initValue}))


			     and NVL(BASIC_BILL,#{BILL_BASE_04}) = #{BILL_BASE_04}

select FIN_CASH_INFO.CASH_ID cashId, FIN_CASH_INFO.FEE_ID feeId, MST_FEEINFO.FEE_TYPE feeType,
FIN_CASH_CALC_RULE.BASIS basis, FIN_CASH_CALC_RULE.BASE_TYPE basicBill, FIN_FLOAT_COUNTING_RULE.FIRST_BASE_TYPE firstBaseType,
FIN_CASH_PAY_RULE.END_TDAY_RULE calcFeeTradeRule, FIN_CASH_PAY_RULE.PAY_TDAY_RULE payFeeTradeRule, FIN_CASH_PAY_RULE.PAY_CYCLE payFeeRule, FIN_FLOAT_COUNTING_RULE.F_ACCR_DATE provisionFirstDay, FIN_CASH_CALC_RULE.YIELD * 100 feeRate, FIN_CASH_CALC_RULE.BASE_DATE_TYPE netAssetValueDay, FIN_FLOAT_COUNTING_RULE.E_ACCR_DATE eAccrDate, FIN_CASH_PAY_RULE.FIRST_PAY_DATE firstCalEndDate, MST_FEEINFO.CHARGE_TYPE chargeType, prd_layer_param.PROD_STYLE prodStyle from FIN_CASH_INFO, MST_FEEINFO, FIN_CASH_PAY_RULE, FIN_CASH_CALC_RULE, FIN_FLOAT_COUNTING_RULE, FIN_PRODUCT left join prd_layer_param on FIN_PRODUCT.FINPROD_ID = prd_layer_param.FINPROD_ID WHERE FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID and FIN_CASH_INFO.CASH_ID = FIN_CASH_CALC_RULE.CASH_ID and (FIN_CASH_CALC_RULE.EFF_DATE = FIN_PRODUCT.VDATE OR FIN_PRODUCT.FINPROD_TYPE2=#{finprodType2}) and FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID and (FIN_CASH_PAY_RULE.EFF_DATE = FIN_PRODUCT.VDATE OR FIN_PRODUCT.FINPROD_TYPE2=#{finprodType2}) and FIN_CASH_INFO.CASH_ID = FIN_FLOAT_COUNTING_RULE.CASH_ID and (FIN_FLOAT_COUNTING_RULE.EFF_DATE = FIN_PRODUCT.VDATE OR FIN_PRODUCT.FINPROD_TYPE2=#{finprodType2}) and (FIN_CASH_INFO.FINPROD_ID = #{finprodId} or prd_layer_param.P_FINPROD_ID = #{finprodId}) and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} and MST_FEEINFO.FEE_TYPE in (#{feeTypeTrust}, #{feeTypeFix}, #{feeTypeSale}, #{feeTypeOthSale}, #{feeTypeThService},#{feeTypeInvest}) and FIN_CASH_INFO.FINPROD_TYPE = #{finprodType}

select  
	from FIN_CASH_PLAN
	where FIN_CASH_PLAN.CASH_ID = (select CASH_ID from FIN_CASH_INFO
									where FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
									    and FIN_CASH_INFO.FINPROD_ID = #{finprodId}
									    and FIN_CASH_INFO.FINPROD_TYPE = #{finprodType}
									    and FIN_CASH_INFO.FEE_ID = #{feeId}

									    	and FIN_CASH_INFO.BRANCH = #{branch}
									    )
	order by FIN_CASH_PLAN.MDATE ASC

	select  FEE_ID id,
